# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TÜRKİSTAN\'DA (ORTA ASYA) KURULAN İLK TÜRK DEVLETLERİ (SB.6.3.1)</text>\n  <rect x="20" y="48" width="210" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. Asya Hun Devleti</text>\n  <text x="125" y="96" text-anchor="middle" font-size="11" fill="#1e3a8a">• Tarihte bilinen İLK Türk devleti</text>\n  <text x="125" y="114" text-anchor="middle" font-size="11" fill="#1e3a8a">• Kurucu: Teoman (Merkez: Ötüken)</text>\n  <text x="125" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">• En Parlak Dönem: Metehan</text>\n  <text x="125" y="156" text-anchor="middle" font-size="11" fill="#1e3a8a">• Onlu Teşkilat (Kara Kuvvetleri</text>\n  <text x="125" y="172" text-anchor="middle" font-size="11" fill="#1e3a8a">kuruluşu: MÖ 209) ve ıslıklı ok</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" fill="#1e3a8a">• Türk boylarını ilk kez tek</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#2563eb">Destan: Oğuz Kağan Destanı</text>\n\n  <rect x="245" y="48" width="210" height="192" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">2. Kök Türk Devleti (I ve II)</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11" fill="#14532d">• «Türk» adını siyasi olarak</text>\n  <text x="350" y="114" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">kullanan İLK devlet (552)</text>\n  <text x="350" y="136" text-anchor="middle" font-size="11" fill="#14532d">• I. Kurucu: Bumin Kağan (İstemi)</text>\n  <text x="350" y="156" text-anchor="middle" font-size="11" fill="#14532d">• II. (Kutluk) Kurucu: Kutluk</text>\n  <text x="350" y="172" text-anchor="middle" font-size="11" fill="#14532d">Kağan, Bilge Kağan, Kül Tigin,</text>\n  <text x="350" y="188" text-anchor="middle" font-size="11" fill="#14532d">Vezir Tonyukuk</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Orhun Yazıtları &amp; Ergenekon</text>\n\n  <rect x="470" y="48" width="210" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">3. Uygur Devleti (744–840)</text>\n  <text x="575" y="96" text-anchor="middle" font-size="11" fill="#713f12">• Kurucu: Kutluk Bilge Kül Kağan</text>\n  <text x="575" y="114" text-anchor="middle" font-size="11" fill="#713a12">• Merkez: Karabalalgasun (Ordu-Balık)</text>\n  <text x="575" y="136" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">• Yerleşik hayata geçen İLK</text>\n  <text x="575" y="152" text-anchor="middle" font-size="11" font-weight="bold" fill="#a16207">Türk devletidir (Bögü Kağan).</text>\n  <text x="575" y="174" text-anchor="middle" font-size="11" fill="#713f12">• Tarım, sulama kanalı, şehir,</text>\n  <text x="575" y="190" text-anchor="middle" font-size="11" fill="#713f12">hareketli harfli matbaa, kâğıt</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Destan: Türeyiş ve Göç Destanı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İLK TÜRK DEVLETLERİNDE DEVLET YÖNETİMİ VE ORDU ANLAYIŞI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">1. Egemenlik, Kut, Töre ve Kurultay</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#155e75">• Kut Anlayışı: Yönetme yetkisinin Gök</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#155e75">Tanrı tarafından kağana verildiğine inanılması.</text>\n  <text x="182" y="142" text-anchor="middle" font-size="11" fill="#155e75">• Töre: Devlet ve toplum hayatını düzenleyen</text>\n  <text x="182" y="158" text-anchor="middle" font-size="11" fill="#155e75">yazısız hukuk kuralları (Kağan da uymak zorunda).</text>\n  <text x="182" y="182" text-anchor="middle" font-size="11" fill="#155e75">• Kurultay (Toy): Devlet işlerinin görüşüldüğü</text>\n  <text x="182" y="198" text-anchor="middle" font-size="11" fill="#155e75">danışma meclisi (Hatun da katılırdı).</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#0e7490">• İkili Teşkilat: Doğu (Kağan) – Batı (Yabgu)</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Ordu-Millet, Ekonomi ve Kültür</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#9d174d">• Ordu-Millet: Eli silah tutan kadın-erkek</text>\n  <text x="517" y="118" text-anchor="middle" font-size="11" fill="#9d174d">her Türk\'ün asker sayılması (ücretli değil).</text>\n  <text x="517" y="142" text-anchor="middle" font-size="11" fill="#9d174d">• Onlu Sistem ve Turan (Hilal) Taktiği.</text>\n  <text x="517" y="166" text-anchor="middle" font-size="11" fill="#9d174d">• İpek ve Kürk Yolu ticareti, demircilik,</text>\n  <text x="517" y="182" text-anchor="middle" font-size="11" fill="#9d174d">dokumacılık (Pazırık Halısı, Altın Elbiseli Adam).</text>\n  <text x="517" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">• Kurgan (mezar), Balbal, 12 Hayvanlı Takvim</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KONARGÖÇER (BOZKIR) YAŞAM İLE YERLEŞİK YAŞAM KARŞILAŞTIRMASI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Konargöçer Yaşam (Hunlar &amp; Kök Türkler)</text>\n  <text x="182" y="102" text-anchor="middle" font-size="11" fill="#1e3a8a">• Coğrafi Etmen: Sert karasal iklim ve bozkır.</text>\n  <text x="182" y="124" text-anchor="middle" font-size="11" fill="#1e3a8a">• Temel Geçim: Hayvancılık (at ve koyun).</text>\n  <text x="182" y="146" text-anchor="middle" font-size="11" fill="#1e3a8a">• Barınma: Keçeden yapılan taşınabilir</text>\n  <text x="182" y="162" text-anchor="middle" font-size="11" fill="#1e3a8a">«Yurt (Otağ)» çadırları; yaylak ve kışlak.</text>\n  <text x="182" y="186" text-anchor="middle" font-size="11" fill="#1e3a8a">• Sanat: Taşınabilir eşyalar (halı, kilim,</text>\n  <text x="182" y="202" text-anchor="middle" font-size="11" fill="#1e3a8a">kemer tokası, kılıç, hayvan üslubu).</text>\n  <text x="182" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Sözlü edebiyat ve kısa süreli hapis cezası</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Yerleşik Yaşam (Uygurlar)</text>\n  <text x="517" y="102" text-anchor="middle" font-size="11" fill="#581c87">• Etmen: Tarım havzaları ve yeni inanç sistemi.</text>\n  <text x="517" y="124" text-anchor="middle" font-size="11" fill="#581c87">• Temel Geçim: Tarım (sulama kanalları) ve ticaret.</text>\n  <text x="517" y="146" text-anchor="middle" font-size="11" fill="#581c87">• Barınma: Surlarla çevrili şehirler (Balık),</text>\n  <text x="517" y="162" text-anchor="middle" font-size="11" fill="#581c87">evler, saraylar ve tapınaklar (mimari gelişti).</text>\n  <text x="517" y="186" text-anchor="middle" font-size="11" fill="#581c87">• Sanat ve Bilim: Fresk (duvar resmi), minyatür,</text>\n  <text x="517" y="202" text-anchor="middle" font-size="11" fill="#581c87">kâğıt, hareketli harfli matbaa, kütüphane.</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">Yazılı hukuk belgeleri ve şehir kültürü</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
